from authlib.integrations.flask_client import OAuth
from flask import Flask, redirect, url_for, session

app = Flask(__name__)
app.secret_key = 'your-secret-key-here'

# Configure Auth0 as the identity provider
oauth = OAuth(app)
auth0 = oauth.register(
    'auth0',
    client_id='YOUR_AUTH0_CLIENT_ID',
    client_secret='YOUR_AUTH0_CLIENT_SECRET',
    api_base_url='https://YOUR_AUTH0_DOMAIN.auth0.com',
    access_token_url='https://YOUR_AUTH0_DOMAIN.auth0.com/oauth/token',
    authorize_url='https://YOUR_AUTH0_DOMAIN.auth0.com/authorize',
    client_kwargs={
        'scope': 'openid profile email',
    },
)

@app.route('/login')
def login():
    return auth0.authorize_redirect(
        redirect_uri=url_for('callback', _external=True),
        audience='https://YOUR_AUTH0_DOMAIN.auth0.com/api/v2/'
    )

@app.route('/callback')
def callback():
    token = auth0.authorize_access_token()
    session['user'] = token
    return redirect('/')
